<script setup lang="ts">import { formatTerm } from '~/utils/formatters'; definePageMeta({ middleware: 'auth' }); const route = useRoute(); const { find } = useCourseOfferings(); const { data: offering } = await useAsyncData(`offering-${route.params.id}`, () => find(Number(route.params.id))); if (!offering.value) throw createError({ statusCode: 404 })</script>
<template><div v-if="offering" class="page-shell"><PageHeader :title="`${offering.course?.course_code} · ${offering.section}`" :description="offering.course?.course_title"><template #actions><StatusBadge :status="offering.status" /><BaseButton :to="`/course-offerings/${offering.id}/edit`">Edit offering</BaseButton></template></PageHeader><div class="grid gap-6 lg:grid-cols-3"><BaseCard class="lg:col-span-2"><dl class="grid gap-5 sm:grid-cols-2"><div><dt class="text-sm text-slate-500">Academic term</dt><dd class="font-semibold">{{ offering.academic_term?.academic_year }} · {{ formatTerm(offering.academic_term?.term ?? '') }}</dd></div><div><dt class="text-sm text-slate-500">Instructor</dt><dd class="font-semibold">{{ offering.instructor?.name ?? 'Unassigned' }}</dd></div><div v-for="schedule in offering.schedules" :key="schedule.id"><dt class="text-sm text-slate-500">Schedule</dt><dd class="font-semibold">{{ schedule.day_of_week }} · {{ schedule.start_time }}–{{ schedule.end_time }}</dd></div></dl></BaseCard><BaseCard><h2 class="font-semibold">Class capacity</h2><p class="mt-4 text-3xl font-bold">{{ offering.enrolled_count ?? 0 }} <span class="text-base font-normal text-slate-400">/ {{ offering.capacity }}</span></p></BaseCard></div></div></template>
